sys_ui_action.script:
(function() {
    var candidateName = current.getValue('u_candidate_name') || 'N/A';
    var nationality   = current.getValue('u_nationality') || 'N/A';
    var passportNum   = current.getValue('u_passport_number') || 'N/A';
    var targetCity    = current.getValue('u_target_city') || 'Germany';
    var visaCategory  = current.u_visa_category.getDisplayValue() || 'EU Blue Card';
    var feeAmount     = current.getValue('u_fee_amount') || '411.00';
    var feeStatus     = current.getDisplayValue('u_fee_status') || 'Unpaid';
    var caseNumber    = current.getValue('number');
    var currentDate   = new GlideDateTime().getDisplayValue();
    var fileName      = 'Vollmacht_' + caseNumber + '.pdf';

    // 1. Build Printable Legal HTML Document
    var htmlContent = '<!DOCTYPE html><html><head><meta charset="utf-8"/>' +
        '<style>' +
        '  body { font-family: Arial, sans-serif; font-size: 11pt; color: #1e293b; padding: 25px; line-height: 1.5; }' +
        '  .header-title { text-align: center; font-size: 16pt; font-weight: bold; margin-bottom: 4px; color: #0f172a; }' +
        '  .header-sub { text-align: center; font-size: 11pt; font-weight: bold; margin-bottom: 25px; color: #475569; }' +
        '  .details-box { border: 1px solid #94a3b8; border-radius: 5px; padding: 12px; margin-bottom: 20px; background: #f8fafc; }' +
        '  .legal-section { margin-bottom: 20px; text-align: justify; }' +
        '  .de-text { font-weight: 500; margin-bottom: 4px; }' +
        '  .en-text { font-style: italic; color: #475569; font-size: 10pt; }' +
        '  .sig-table { width: 100%; margin-top: 50px; border-collapse: collapse; }' +
        '  .sig-line { border-bottom: 1px solid #000; height: 35px; width: 90%; }' +
        '</style>' +
        '</head><body>' +
        '  <div class="header-title">VOLLMACHT (POWER OF ATTORNEY)</div>' +
        '  <div class="header-sub">gemäß § 81a AufenthG – Beschleunigtes Fachkräfteverfahren</div>' +

        '  <div class="details-box">' +
        '    <strong>Vollmachtgeber (Applicant):</strong> ' + candidateName + '<br/>' +
        '    <strong>Staatsangehörigkeit (Nationality):</strong> ' + nationality + '<br/>' +
        '    <strong>Passnummer (Passport No.):</strong> ' + passportNum + '<br/>' +
        '    <strong>Zuständige Behörde (Target Authority):</strong> Ausländerbehörde ' + targetCity + '<br/>' +
        '    <strong>Verfahren / Visa Category:</strong> ' + visaCategory + '<br/>' +
        '    <strong>Aktenzeichen (Case Reference):</strong> ' + caseNumber + '<br/>' +
        '    <strong>Gebühr (Statutory Fee):</strong> €' + feeAmount + ' (' + feeStatus + ')' +
        '  </div>' +

        '  <div class="legal-section">' +
        '    <div class="de-text">Hiermit bevollmächtige ich die antragstellende Arbeitgeberin, alle im Rahmen des beschleunigten Fachkräfteverfahrens nach § 81a AufenthG erforderlichen Anträge und Erklärungen für mich bei der zuständigen Ausländerbehörde, der Bundesagentur für Arbeit sowie den Auslandsvertretungen abzugeben und entgegenzunehmen.</div>' +
        '    <div class="en-text">I hereby authorize the sponsoring employer to submit and receive all declarations, legal documents, and official notifications necessary for the accelerated skilled worker procedure under Section 81a of the German Residence Act (AufenthG).</div>' +
        '  </div>' +

        '  <table class="sig-table">' +
        '    <tr>' +
        '      <td style="width: 50%; vertical-align: bottom;">' +
        '        <div class="sig-line"></div>' +
        '        <small>Ort, Datum (City, Date)</small>' +
        '      </td>' +
        '      <td style="width: 50%; vertical-align: bottom;">' +
        '        <div class="sig-line"></div>' +
        '        <small>Unterschrift Vollmachtgeber (Candidate Signature)</small>' +
        '      </td>' +
        '    </tr>' +
        '  </table>' +
        '</body></html>';

    // 2. Generate Real PDF Attachment
    var pdfApi = new sn_pdfgeneratorutils.PDFGenerationAPI();
    var result = pdfApi.convertToPDF(
        htmlContent,
        current.getTableName(),
        current.getUniqueValue(),
        fileName
    );

    // 3. Handle PDF Generation Result
    if (result && result.attachment_id) {
        current.work_notes = "Official Vollmacht PDF compiled and attached: " + fileName + "\nGenerated by: " + gs.getUserDisplayName() + " on " + currentDate;
        current.u_poa_signed = false; // Remains false until candidate signs and returns it
        current.update();

        // Update child document tracking record
        var docGr = new GlideRecord('x_2023506_german_1_case_doc');
        docGr.addQuery('u_case', current.getUniqueValue());
        docGr.addQuery('u_document_name', 'CONTAINS', 'Vollmacht');
        docGr.query();
        if (docGr.next()) {
            docGr.u_status = 'generated';
            docGr.u_review_notes = 'Vollmacht generated via UI Action on ' + currentDate + '. Awaiting candidate signature.';
            docGr.update();
        }

        // Fire outbound email event with attachment
        gs.eventQueue('x_2023506_german_1.vollmacht_generated', current, current.u_candidate_email, candidateName);

        gs.addInfoMessage("Vollmacht PDF generated and attached successfully.");
    } else {
        gs.error("Failed to generate Vollmacht PDF: " + JSON.stringify(result));
        gs.addErrorMessage("Could not generate PDF. Please ensure the 'PDF Generation API' plugin is active.");
    }

    action.setRedirectURL(current);
})();
